class Skiplist {
    private static final int MAX_LEVEL = 16;
    private static final int CAPACITY = 50005;
    private final int[][] next;
    private final int[] value;
    private final Random random;
    private int currentLevel;
    private int nodeCount;

    public Skiplist() {
        next = new int[CAPACITY][MAX_LEVEL];
        value = new int[CAPACITY];
        random = new Random(2);
        currentLevel = 1;
        nodeCount = 0;
    }

    public boolean search(int target) {
        int cur = 0;
        for (int level = currentLevel - 1; level >= 0; level--) {
            while (next[cur][level] != 0 && value[next[cur][level]] < target) {
                cur = next[cur][level];
            }
        }
        int candidate = next[cur][0];
        return candidate != 0 && value[candidate] == target;
    }

    public void add(int num) {
        int[] update = predecessors(num);
        int level = randomLevel();
        if (level > currentLevel) {
            Arrays.fill(update, currentLevel, level, 0);
            currentLevel = level;
        }
        int id = ++nodeCount;
        value[id] = num;
        for (int i = 0; i < level; i++) {
            next[id][i] = next[update[i]][i];
            next[update[i]][i] = id;
        }
    }

    public boolean erase(int num) {
        int[] update = predecessors(num);
        int target = next[update[0]][0];
        if (target == 0 || value[target] != num) {
            return false;
        }
        for (int i = 0; i < currentLevel; i++) {
            if (next[update[i]][i] == target) {
                next[update[i]][i] = next[target][i];
            }
        }
        while (currentLevel > 1 && next[0][currentLevel - 1] == 0) {
            currentLevel--;
        }
        return true;
    }

    private int[] predecessors(int target) {
        int[] update = new int[MAX_LEVEL];
        int cur = 0;
        for (int level = currentLevel - 1; level >= 0; level--) {
            while (next[cur][level] != 0 && value[next[cur][level]] < target) {
                cur = next[cur][level];
            }
            update[level] = cur;
        }
        return update;
    }

    private int randomLevel() {
        int level = 1;
        while (level < MAX_LEVEL && random.nextBoolean()) {
            level++;
        }
        return level;
    }
}

class Skiplist {
    private static final int MAX_LEVEL = 16;
    private final Node head;
    private int currentLevel;
    private int inserted;

    private static class Node {
        int val;
        Node[] next;

        Node(int val, int level) {
            this.val = val;
            this.next = new Node[level];
        }
    }

    public Skiplist() {
        head = new Node(-1, MAX_LEVEL);
        currentLevel = 1;
    }

    public boolean search(int target) {
        Node cur = head;
        for (int level = currentLevel - 1; level >= 0; level--) {
            while (cur.next[level] != null && cur.next[level].val < target) {
                cur = cur.next[level];
            }
        }
        cur = cur.next[0];
        return cur != null && cur.val == target;
    }

    public void add(int num) {
        Node[] update = predecessors(num);
        int level = deterministicLevel();
        if (level > currentLevel) {
            for (int i = currentLevel; i < level; i++) {
                update[i] = head;
            }
            currentLevel = level;
        }
        Node node = new Node(num, level);
        for (int i = 0; i < level; i++) {
            node.next[i] = update[i].next[i];
            update[i].next[i] = node;
        }
    }

    public boolean erase(int num) {
        Node[] update = predecessors(num);
        Node target = update[0].next[0];
        if (target == null || target.val != num) {
            return false;
        }
        for (int i = 0; i < currentLevel && i < target.next.length; i++) {
            if (update[i].next[i] == target) {
                update[i].next[i] = target.next[i];
            }
        }
        while (currentLevel > 1 && head.next[currentLevel - 1] == null) {
            currentLevel--;
        }
        return true;
    }

    private Node[] predecessors(int target) {
        Node[] update = new Node[MAX_LEVEL];
        Node cur = head;
        for (int level = currentLevel - 1; level >= 0; level--) {
            while (cur.next[level] != null && cur.next[level].val < target) {
                cur = cur.next[level];
            }
            update[level] = cur;
        }
        return update;
    }

    private int deterministicLevel() {
        int x = ++inserted;
        int level = 1;
        while (level < MAX_LEVEL && (x & 1) == 0) {
            level++;
            x >>= 1;
        }
        return level;
    }
}

class Skiplist {
    private int[] values;
    private int size;

    public Skiplist() {
        values = new int[8];
    }

    public boolean search(int target) {
        int index = lowerBound(target);
        return index < size && values[index] == target;
    }

    public void add(int num) {
        ensureCapacity(size + 1);
        int index = lowerBound(num);
        System.arraycopy(values, index, values, index + 1, size - index);
        values[index] = num;
        size++;
    }

    public boolean erase(int num) {
        int index = lowerBound(num);
        if (index == size || values[index] != num) {
            return false;
        }
        System.arraycopy(values, index + 1, values, index, size - index - 1);
        size--;
        return true;
    }

    private int lowerBound(int target) {
        int left = 0;
        int right = size;
        while (left < right) {
            int mid = left + (right - left) / 2;
            if (values[mid] < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        return left;
    }

    private void ensureCapacity(int needed) {
        if (needed <= values.length) {
            return;
        }
        int[] next = new int[values.length * 2];
        System.arraycopy(values, 0, next, 0, size);
        values = next;
    }
}

class Skiplist {
    private static final int MAX_VALUE = 20000;
    private final int[] count;

    public Skiplist() {
        count = new int[MAX_VALUE + 1];
    }

    public boolean search(int target) {
        return count[target] > 0;
    }

    public void add(int num) {
        count[num]++;
    }

    public boolean erase(int num) {
        if (count[num] == 0) {
            return false;
        }
        count[num]--;
        return true;
    }
}
